    "  exit 1",
    "fi",
    "python3 " + q(scriptPath) + " \\",
    "  --template " + q(templateFolder) + " \\",
    "  --jobs " + q(jobsFolder) + " \\",
    "  --name " + q(form.name) + " \\",
    "  --id " + q(form.id) + " \\",
    "  --clip " + q(form.clip) + " \\",
    "  --project " + q(projectFileName),
    "BASH",
  ].join("\n");
})()}}

={{(() => {
  const q = (value) => "'" + String(value ?? "").replace(/'/g, "'\\''") + "'";
  const afterEffectsBinary = "/Applications/Adobe After Effects 2026/Adobe After Effects 2026.app/Contents/MacOS/After Effects";
  const stdout = String($("Copy and edit").item.json.stdout ?? "");
  const line = stdout.split("\n").reverse().find((row) => row.startsWith("AE_JOB "));
  if (!line) {
    throw new Error("The copy step did not report the new folder.");
  }
  const job = JSON.parse(line.slice("AE_JOB ".length));
  const dest = q(job.destination);
  const ae = q(afterEffectsBinary);
  return [
    "bash <<'BASH'",
    "set -euo pipefail",
    "dest=" + dest,
    "ae=" + ae,
    "if [ ! -d \"$dest\" ]; then",
    "  echo \"Destination folder does not exist: $dest\" >&2",
    "  exit 1",
    "fi",
    "if [ ! -e \"$ae\" ]; then",
    "  echo \"After Effects binary not found: $ae\" >&2",
    "  exit 1",
    "fi",
    "if [ ! -x \"$ae\" ]; then",
    "  echo \"After Effects binary is not executable: $ae\" >&2",
    "  exit 1",
    "fi",
    "dest_real=$(cd \"$dest\" && pwd -P)",
    "jsx=\"$dest_real/ae-relink.jsx\"",
    "log=\"$dest_real/ae-launch.log\"",
    "if [ ! -f \"$jsx\" ]; then",
    "  echo \"JSX file not found: $jsx\" >&2",
    "  exit 1",
    "fi",
    "nohup \"$ae\" -r \"$jsx\" > \"$log\" 2>&1 &",
    "pid=$!",
    "sleep 1",
    "if ! kill -0 \"$pid\" 2>/dev/null; then",
    "  echo \"After Effects exited immediately. Log: $log\" >&2",
    "  cat \"$log\" >&2",
    "  exit 1",
    "fi",
    "echo \"Started After Effects pid $pid\"",
    "echo \"Folder: $dest_real\"",
    "echo \"Log: $log\"",
    "echo \"Quit After Effects before the next run if it is still open.\"",
    "BASH",
  ].join("\n");
})()}}
